fn main() {
    let add_one = |x| x + 1;
    let add = |a: i32, b: i32| -> i32 { a + b };
    let greet = || println!("hello from a closure");

    println!("{}", add_one(5));
    println!("{}", add(2, 3));
    greet();
}

fn apply_twice(f: impl Fn(i32) -> i32, value: i32) -> i32 {
    f(f(value))
}

fn double(x: i32) -> i32 {
    x * 2
}

fn main() {
    let add_ten = |x| x + 10;
    println!("{}", apply_twice(add_ten, 1));
    println!("{}", apply_twice(double, 3));
    println!("{}", apply_twice(|x| x * x, 3));
}

fn main() {
    let mut words = vec!["pear", "fig", "banana", "kiwi"];
    words.sort_by_key(|w| w.len());
    println!("{:?}", words);

    let nickname: Option<String> = None;
    let shown = nickname.unwrap_or_else(|| String::from("guest"));
    println!("{shown}");
}

// Output:
// ["fig", "pear", "kiwi", "banana"]
// guest

