exercise.solution:
fn apply(f: impl Fn(i32) -> i32, value: i32) -> i32 {
    f(value)
}

fn minus_five_of(value: i32) -> i32 {
    let minus_five = |x| x - 5;
    apply(minus_five, value)
}

fn main() {
    let doubled = apply(|x| x * 2, 21);
    println!("{doubled}");
    println!("{}", minus_five_of(50));
}
